CREATE TABLE public.meta_connector_campaigns (id uuid PRIMARY KEY, created_by uuid NOT NULL, account_id text NOT NULL, page_id text NOT NULL, name text NOT NULL, draft jsonb NOT NULL DEFAULT '{}'::jsonb, remote jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'DRAFT', last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.meta_connector_campaigns TO authenticated; GRANT ALL ON public.meta_connector_campaigns TO service_role; ALTER TABLE public.meta_connector_campaigns ENABLE ROW LEVEL SECURITY; CREATE POLICY meta_connector_read ON public.meta_connector_campaigns FOR SELECT TO authenticated USING (public.user_has_permission(auth.uid(), 'comm_meta_connector_campaigns', 'can_read')); CREATE INDEX meta_connector_campaigns_created_at_idx ON public.meta_connector_campaigns(created_at DESC);